import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  useParams,
  createMemoryHistory,
} from '@tanstack/react-router';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export function UserView() {
  const { id } = useParams({ from: userRoute.id });
  return <p>user: {id}</p>;
}

export const userRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/users/$id',
  parseParams: (p: { id: string }) => ({ id: Number(p.id) }),
  component: UserView,
});

const routeTree = rootRoute.addChildren([userRoute]);

export function makeRouter(initialEntries: string[] = ['/users/42']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
